  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 The Thread of Promise: The Covenants$j$, $j${"readings": [{"title": "Genesis 12 (King James Version)", "url": "/portal/bible/Genesis/12"}, {"title": "2 Samuel 7 (King James Version)", "url": "/portal/bible/2Samuel/7"}, {"title": "Jeremiah 31 (King James Version)", "url": "/portal/bible/Jeremiah/31"}, {"title": "Luke 24 (King James Version)", "url": "/portal/bible/Luke/24"}], "body": "Read Genesis 12, 2 Samuel 7, Jeremiah 31 and Luke 24 in the King James Version. Then read this lesson.\n\nA covenant is a binding agreement in which God makes promises to His people. The Old Testament is built on a chain of covenants. In the garden God promised a deliverer. With Noah He promised never again to destroy the earth by a flood. With Abraham He promised a land, a nation and a blessing for all families of the earth. At Sinai He made a covenant with Israel and gave the law. With David He promised an everlasting throne. Through Jeremiah He promised a new covenant written on the heart. After His resurrection, Jesus told His disciples that the law, the prophets and the psalms all spoke of Him.\n\nKey words: covenant, promise, fulfillment, seed, blessing.\n\nYour task: (1) List four covenants from the Old Testament and one promise in each. (2) Explain how Genesis 12:3 reaches beyond Israel. (3) Tell what Jesus said about the Scriptures in Luke 24:44.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to the final unit of Old Testament Survey. Over five units we have walked through the Law, the history, the poetry and the prophets. Now we step back and ask one question. How does it all fit together? The answer is that one story runs through the whole Old Testament, and that story is a promise.\n\nThink of the Old Testament as a thread. At the very start, in Genesis 3:15, God promised a deliverer who would defeat the serpent. That thread is picked up again and again. Each time God makes a covenant, the thread becomes clearer.\n\nRemember what a covenant is. A covenant is a binding agreement where God commits Himself to His people. Let's trace them.\n\nGod made a covenant with Noah after the flood and promised never again to destroy the earth with water, and He set the rainbow as a sign. With Abraham, God promised a land, a great nation, and a blessing to the world. Genesis 12:3 says, and in thee shall all families of the earth be blessed. That means the promise was never meant for Israel only. At Sinai, God made a covenant with the nation of Israel and gave them the law so they would know how to live as His people.\n\nWith David, God promised in 2 Samuel 7 that his throne would be established for ever. Then through the prophets, God promised something even greater. Jeremiah 31:31 says, Behold, the days come, saith the LORD, that I will make a new covenant with the house of Israel, and with the house of Judah. Verse 33 says, I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people.\n\nNow listen to what Jesus Christ said after He rose from the dead. He met His disciples and reminded them that everything in the Scriptures pointed to Him. Luke 24:44 says, These are the words which I spake unto you, while I was yet with you, that all things must be fulfilled, which were written in the law of Moses, and in the prophets, and in the psalms, concerning me. The Law, the Prophets and the Writings were not separate stories. They are one story, and Jesus Christ is its center.\n\nYour task is to list four covenants and a promise in each, explain how Genesis 12:3 reaches beyond Israel, and tell what Jesus said in Luke 24:44. Then take the four question check.\n\nThe Old Testament is one story, and the story is about Him. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 The Thread of Promise: The Covenants$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Prophecies of the Messiah$j$, $j${"readings": [{"title": "Isaiah 7 (King James Version)", "url": "/portal/bible/Isaiah/7"}, {"title": "Isaiah 53 (King James Version)", "url": "/portal/bible/Isaiah/53"}, {"title": "Micah 5 (King James Version)", "url": "/portal/bible/Micah/5"}, {"title": "Psalm 22 (King James Version)", "url": "/portal/bible/Psalms/22"}, {"title": "Psalm 110 (King James Version)", "url": "/portal/bible/Psalms/110"}], "body": "Read Isaiah 7:10 to 14, Isaiah 53, Micah 5:1 to 5, Psalm 22 and Psalm 110 in the King James Version. Then read this lesson.\n\nThe word Messiah means anointed one, and the Greek form is Christ. The Old Testament contains many promises about this coming Savior, spoken hundreds of years before His birth. A virgin would conceive and bear a son named Immanuel. He would be born in Bethlehem. He would enter Jerusalem as a lowly King on a donkey. He would suffer for the sins of others, as Isaiah 53 describes, and Psalm 22 describes His suffering on the cross. Psalm 110 shows Him seated at the right hand of God. The New Testament shows that Jesus Christ fulfilled each of these.\n\nKey words: Messiah, Immanuel, suffering servant, fulfillment, anointed.\n\nYour task: (1) Name the town where Micah 5:2 says the ruler would be born. (2) Say what Immanuel means. (3) Tell two things Isaiah 53 says about the servant who suffered.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Last time we saw that the Old Testament is one story of promise. Today we look at specific prophecies about the coming Savior. The word Messiah means the anointed one. In Greek, that word is Christ. The prophets spoke of Him long before He came.\n\nLook at what Isaiah wrote around seven hundred years before Christ. Isaiah 7:14 says, Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel. When the New Testament quotes this verse in Matthew 1:23, it adds, which being interpreted is, God with us. The Savior would not be only a man sent from God. God Himself would come to be with us. First Timothy 3:16 says it plainly, God was manifest in the flesh.\n\nNext, the place of His birth. Micah wrote about seven hundred years before Christ that the ruler of Israel would come from Bethlehem. Micah 5:2 says, But thou, Bethlehem Ephratah, though thou be little among the thousands of Judah, yet out of thee shall he come forth unto me that is to be ruler in Israel; whose goings forth have been from of old, from everlasting. And Zechariah 9:9 told that the King would arrive in Jerusalem lowly, riding upon an ass.\n\nThe most striking prophecy is Isaiah 53, which describes a servant who would suffer for the sins of others. Isaiah 53:5 says, But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed. And verse 6 says, All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all. Read the chapter slowly and think about the cross.\n\nPsalm 22 also describes the suffering of the Messiah. David wrote about a thousand years before Christ, and he began, My God, my God, why hast thou forsaken me? Verse 16 says, they pierced my hands and my feet. David wrote those words long before the Romans ever used crucifixion.\n\nFinally, Psalm 110:1 says, The LORD said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool. The Messiah was not only to suffer. He was to reign.\n\nYour task is to name the town Micah mentions, tell what Immanuel means, and give two things Isaiah 53 says about the suffering servant. Then take the four question check.\n\nThe Savior was promised, and the Savior came. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Prophecies of the Messiah$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Sacrifice, Priesthood and the Prophet like Moses$j$, $j${"readings": [{"title": "Genesis 22 (King James Version)", "url": "/portal/bible/Genesis/22"}, {"title": "Leviticus 16 (King James Version)", "url": "/portal/bible/Leviticus/16"}, {"title": "Leviticus 17 (King James Version)", "url": "/portal/bible/Leviticus/17"}, {"title": "Deuteronomy 18 (King James Version)", "url": "/portal/bible/Deuteronomy/18"}, {"title": "John 1 (King James Version)", "url": "/portal/bible/John/1"}], "body": "Read Genesis 22:1 to 14, Leviticus 16 and 17:11, Deuteronomy 18:15 to 19 and John 1 in the King James Version. Then read this lesson.\n\nThe sacrifices, priests and feasts of the Old Testament taught Israel that sin is serious and that forgiveness comes at a cost. On Mount Moriah Abraham told Isaac that God would provide Himself a lamb. At the Passover a lamb's blood marked each house. On the Day of Atonement the high priest brought blood into the holy place. Leviticus 17:11 says that the life of the flesh is in the blood and that blood makes an atonement for the soul. Moses also promised a Prophet like himself whom the people must hear. The New Testament shows that Jesus Christ is the Lamb of God, the High Priest and the Prophet that Moses promised.\n\nKey words: sacrifice, atonement, blood, priest, Lamb.\n\nYour task: (1) Tell what Abraham said God would provide in Genesis 22:8. (2) Explain why blood was used in the sacrifices (Leviticus 17:11). (3) Write what John the Baptist said when he saw Jesus (John 1:29).\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we look at the sacrifices, the priests and the prophet that the Law promised. These pictures can seem strange at first, but they were teaching Israel something very important. Sin is serious, and forgiveness has a cost.\n\nGo back to the story of Abraham and Isaac on Mount Moriah. God told Abraham to offer his son. As they walked up the mountain, Isaac asked, Behold the fire and the wood: but where is the lamb for a burnt offering? Abraham answered in Genesis 22:8, My son, God will provide himself a lamb for a burnt offering. At the last moment God stopped Abraham and provided a ram caught in a thicket. Abraham had spoken more than he knew.\n\nThink again about the Passover. In Exodus 12:13 God said, when I see the blood, I will pass over you. The lamb died so that the household could live. Every year after that, Israel remembered that night.\n\nLeviticus gives the reason that blood was so important. Leviticus 17:11 says, For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls. Atonement means covering for sin. Once a year, on the Day of Atonement, the high priest took blood into the most holy place for the sins of the nation. But the sacrifices had to be repeated again and again, which showed that they pointed to something greater.\n\nMoses also gave a promise about a prophet. In Deuteronomy 18:15 he said, The LORD thy God will raise up unto thee a Prophet from the midst of thee, of thy brethren, like unto me; unto him ye shall hearken. Moses was a deliverer, a lawgiver and a mediator. The Prophet to come would be all of that and more.\n\nWhen John the Baptist saw Jesus coming to him, he said these words. John 1:29 says, Behold the Lamb of God, which taketh away the sin of the world. The lamb of the Passover, the lamb that Abraham promised, the offerings of the altar and the sacrifices of the Day of Atonement all pointed to Jesus Christ, who gave His life for the sins of the world. He is also our High Priest and the Prophet that Moses promised.\n\nYour task is to tell what Abraham said God would provide, explain why blood was used in the sacrifices, and write what John the Baptist said when he saw Jesus. Then take the four question check.\n\nThe sacrifices pointed to the Savior who would give His life for us. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Sacrifice, Priesthood and the Prophet like Moses$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Between the Testaments and the Fullness of Time$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}, {"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}, {"title": "Malachi 4 (King James Version)", "url": "/portal/bible/Malachi/4"}, {"title": "Galatians 4 (King James Version)", "url": "/portal/bible/Galatians/4"}], "body": "Read Isaiah 40:1 to 5, Malachi 3:1, Malachi 4:1 to 6 and Galatians 4:1 to 7 in the King James Version. Then read this lesson.\n\nAfter Malachi there were about four hundred years in which no prophet spoke. These years are called the time between the testaments. During that time the Persian Empire gave way to Greece under Alexander the Great, and then Rome ruled the world. Greek became a common language, roads were built, and the Jewish people lived scattered in many cities, each with a synagogue. This prepared the world for the gospel. Galatians 4:4 says that when the fulness of the time was come, God sent forth his Son. Malachi and Isaiah both promised a messenger to prepare the way. In the New Testament this messenger is John the Baptist.\n\nKey words: silence, fullness of time, messenger, preparation, gospel.\n\nYour task: (1) Explain what happened between the testaments. (2) Name the messenger Malachi and Isaiah promised. (3) Write Galatians 4:4 in your own words and tell why the timing mattered.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We have come to the last lesson in Old Testament Survey. What happens after Malachi? The Old Testament ends, and then there are about four hundred years of silence. No new prophet spoke for God during that time. The Jewish people were waiting.\n\nThose four hundred years were not wasted. God was preparing the world. The Persian Empire, which had let the Jews go home, was conquered by Alexander the Great of Greece. Wherever his armies went, the Greek language spread. Later, Rome took control, and the Romans built roads and kept peace across much of the known world. Jews lived in many cities, and in each place they met in synagogues to read the Scriptures. All of this made it possible for the gospel to spread quickly.\n\nScripture says this in Galatians 4:4, But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law. God has a perfect timetable. The promises of Genesis, the covenant with David and the words of the prophets came together at exactly the right time.\n\nThe prophets also promised a messenger to prepare the way. Isaiah 40:3 says, The voice of him that crieth in the wilderness, Prepare ye the way of the LORD, make straight in the desert a highway for our God. And Malachi 3:1 says, Behold, I will send my messenger, and he shall prepare the way before me. In the New Testament, John the Baptist appears in the wilderness and fulfills these words. After four hundred years, a prophetic voice was heard again.\n\nThe Old Testament does not end with a finished story. It ends with a promise and an open door. Malachi 4:2 says, But unto you that fear my name shall the Sun of righteousness arise with healing in his wings. Everything we have studied, the creation, the covenant, the Law, the kings, the prophets and the promises, was pointing toward the Savior, Jesus Christ.\n\nYour task is to explain what happened between the testaments, name the messenger Malachi and Isaiah promised, and write Galatians 4:4 in your own words. Then take the four question check and the Unit 6 quiz. After that you will be ready for the Final Assessment and the Final Exam.\n\nYou have read the whole story, and now you are ready for the Savior it promises. Excellence, Faith, Purpose. Thank you for studying the Old Testament with me."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Between the Testaments and the Fullness of Time$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: The Promise Fulfilled$j$, $j${"prompt": "Choose one Old Testament prophecy about the Messiah from this unit: Genesis 3:15, Isaiah 7:14, Isaiah 53, Micah 5:2, Psalm 22 or Zechariah 9:9. Write one paragraph of 150 to 200 words. Quote the prophecy from the King James Version, explain what it promised, and tell how the New Testament shows that Jesus Christ fulfilled it. Then say what that fulfillment means for a student today.", "rubric": "Total 100. Accurate prophecy quoted from the King James Version: 25. Explains what the prophecy promised: 25. Shows how Jesus Christ fulfilled it: 25. Clear writing and correct conventions: 25."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: The Promise Fulfilled$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: The Whole Story$j$, $j${"prompt": "After reading the Old Testament from Genesis to Malachi, what part of the story spoke to you most? Name the book or passage, say what it taught you about God, and tell how it could change the way you live. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: The Whole Story$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: The Thread of Promise: The Covenants$j$, $j${"questions": [{"q": "What is a covenant?", "options": ["A binding agreement in which God commits Himself to His people", "A list of kings", "A kind of poem", "A type of offering"]}, {"q": "Which covenant promised a land, a nation and a blessing to all families of the earth?", "options": ["The covenant at Sinai", "The covenant with Abraham", "The covenant with David", "The covenant with Noah"]}, {"q": "What did God promise David in 2 Samuel 7?", "options": ["A throne that would be established for ever", "A new temple of stone", "A new law", "A great flood"]}, {"q": "According to Luke 24:44, what did Jesus say about the law of Moses, the prophets and the psalms?", "options": ["They were no longer needed", "They belonged to the priests alone", "They were only history", "They were written concerning Him"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: The Thread of Promise: The Covenants$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,3}'::int[], array[$j$A covenant is a binding agreement with promises that God makes to His people.$j$,$j$God promised Abraham a land, a nation and a blessing for all families of the earth (Genesis 12:1 to 3).$j$,$j$God promised that David's house, kingdom and throne would last for ever.$j$,$j$Jesus said that all things written in the law, the prophets and the psalms concerned Him.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: The Thread of Promise: The Covenants$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Prophecies of the Messiah$j$, $j${"questions": [{"q": "What does the word Messiah mean?", "options": ["Priest of the temple", "Anointed one", "King of Egypt", "Teacher"]}, {"q": "What does Immanuel mean, according to Matthew 1:23?", "options": ["The mighty king", "God with us", "Prince of peace", "Son of David"]}, {"q": "Which town did Micah 5:2 name as the place the ruler would come from?", "options": ["Jericho", "Jerusalem", "Nazareth", "Bethlehem"]}, {"q": "Which chapter describes a servant who was wounded for our transgressions?", "options": ["Psalm 23", "Micah 6", "Genesis 22", "Isaiah 53"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prophecies of the Messiah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,3}'::int[], array[$j$Messiah means anointed one, and the Greek form is Christ.$j$,$j$Matthew 1:23 says Immanuel means God with us.$j$,$j$Micah named Bethlehem Ephratah.$j$,$j$Isaiah 53 describes the suffering servant.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Prophecies of the Messiah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$, $j${"questions": [{"q": "What did Abraham tell Isaac that God would provide in Genesis 22:8?", "options": ["A fortress", "A lamb for a burnt offering", "A king", "A new land"]}, {"q": "According to Leviticus 17:11, why was blood used on the altar?", "options": ["The life of the flesh is in the blood, to make an atonement for the soul", "It made the altar clean", "It pleased the priests", "It was a symbol of war"]}, {"q": "What did Moses promise in Deuteronomy 18:15?", "options": ["That the temple would be taken away", "That the law would end", "That God would raise up a Prophet like Moses", "That Israel would have no more prophets"]}, {"q": "What did John the Baptist say when he saw Jesus?", "options": ["Behold the sign of Jonah", "Behold the temple of the LORD", "Behold the king of Babylon", "Behold the Lamb of God, which taketh away the sin of the world"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,3}'::int[], array[$j$Abraham said, God will provide himself a lamb for a burnt offering.$j$,$j$Blood made atonement for the soul because the life is in the blood.$j$,$j$Moses said God would raise up a Prophet like unto him.$j$,$j$John 1:29 records this declaration.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Sacrifice, Priesthood and the Prophet like Moses$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Between the Testaments and the Fullness of Time$j$, $j${"questions": [{"q": "About how many years passed between Malachi and the New Testament?", "options": ["One thousand", "Four hundred", "One hundred", "Forty"]}, {"q": "Which empire spread the Greek language across the known world?", "options": ["Egypt", "Assyria", "Greece under Alexander the Great", "Babylon"]}, {"q": "Who is the messenger Isaiah and Malachi promised in the New Testament?", "options": ["Peter", "Paul", "Stephen", "John the Baptist"]}, {"q": "What does Galatians 4:4 say about the timing of God's sending His Son?", "options": ["It happened by chance", "It happened before Abraham", "It happened when the fulness of the time was come", "It happened too late"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Between the Testaments and the Fullness of Time$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,2}'::int[], array[$j$About four hundred years passed with no new prophet.$j$,$j$Alexander's conquests spread the Greek language.$j$,$j$John the Baptist prepared the way for Jesus.$j$,$j$God sent forth His Son when the fulness of the time was come.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Between the Testaments and the Fullness of Time$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Promise and Fulfillment, Christ in the Old Testament$j$, $j${"questions": [{"q": "Which verse is the first promise of a deliverer in the Bible?", "options": ["Exodus 20:3", "Genesis 3:15", "Psalm 23:1", "Genesis 1:1"]}, {"q": "What did God promise Abraham about all families of the earth?", "options": ["They would be destroyed", "They would be scattered", "They would be blessed in him", "They would serve Israel"]}, {"q": "Which prophet said a virgin would conceive and bear a son named Immanuel?", "options": ["Amos", "Jeremiah", "Jonah", "Isaiah"]}, {"q": "Where did Micah say the ruler of Israel would be born?", "options": ["Jericho", "Bethlehem", "Samaria", "Nazareth"]}, {"q": "What did Jesus say that the Scriptures were about, according to Luke 24:44?", "options": ["Only the temple", "Only the law", "The history of Rome", "Himself"]}, {"q": "What does the Lamb of the Passover and the sacrifices point to?", "options": ["Jesus Christ, the Lamb of God", "The Greek language", "The kings of Judah", "The temple walls"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Promise and Fulfillment, Christ in the Old Testament$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,1,3,0}'::int[], array[$j$Genesis 3:15 speaks of the seed of the woman who would bruise the serpent's head.$j$,$j$Genesis 12:3 says in thee shall all families of the earth be blessed.$j$,$j$Isaiah 7:14 contains this prophecy.$j$,$j$Micah 5:2 names Bethlehem Ephratah.$j$,$j$Jesus said the law, the prophets and the psalms were written concerning Him.$j$,$j$John 1:29 calls Jesus the Lamb of God, which taketh away the sin of the world.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Promise and Fulfillment, Christ in the Old Testament$j$ on conflict (item_id) do nothing;
